import re

def top_split(text,word):
    parts=[];start=0;depth=0;quote=None;i=0;upper=text.upper();needle=" "+word.upper()+" "
    while i<len(text):
        c=text[i]
        if quote:
            if c==quote:
                if i+1<len(text) and text[i+1]==quote:i+=2;continue
                quote=None
        elif c in "'\"`":quote=c
        elif c=='(':depth+=1
        elif c==')':depth-=1
        elif depth==0 and upper.startswith(needle,i):
            parts.append(text[start:i].strip());i+=len(needle);start=i;continue
        i+=1
    if parts:parts.append(text[start:].strip());return parts
    return [text.strip()]

def find_where(sql):
    clean=re.sub(r"--[^\n]*|/\*.*?\*/"," ",sql,flags=re.S)
    m=re.search(r"\bWHERE\b",clean,re.I)
    if not m:return ""
    start=m.end();depth=0;quote=None;i=start;tail=clean[start:]
    while i<len(clean):
        c=clean[i]
        if quote:
            if c==quote:
                if i+1<len(clean) and clean[i+1]==quote:i+=2;continue
                quote=None
        elif c in "'\"`":quote=c
        elif c=='(':depth+=1
        elif c==')':depth-=1
        elif depth==0:
            clause=re.match(r"\s+(GROUP\s+BY|ORDER\s+BY|LIMIT|QUALIFY|WINDOW)\b",clean[i:],re.I)
            if clause:return clean[start:i].strip()
        i+=1
    return clean[start:].strip()

def atom_has_partition_filter(atom,column):
    col=r"(?:`?"+re.escape(column)+r"`?)"
    return bool(re.search(r"(?<![\w.])"+col+r"\s*(?:=|>=|<=|>|<)\s*(?:DATE\s*)?(?:TIMESTAMP\s*)?(?:@\w+|\?|['\"].*?['\"]|CURRENT_DATE\s*\(\s*\))",atom,re.I))

def partition_filter_report(sql,partition_column):
    where=find_where(sql)
    if not where:return {"accepted":False,"reason":"where_clause_missing","action":"add a direct filter on the partition column"}
    disjuncts=top_split(where,"OR")
    failures=[]
    for index,branch in enumerate(disjuncts):
        conjunctions=top_split(branch,"AND")
        if not any(atom_has_partition_filter(atom,partition_column) for atom in conjunctions):failures.append(index)
    return {"accepted":not failures,"reason":"partition_filter_present_in_every_or_branch" if not failures else "partition_filter_missing_from_or_branch",
        "unfiltered_or_branches":failures,"action":"add a direct, pruning-compatible partition-column predicate to every OR branch; validate with BigQuery dry run and compare result rows"}
